"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type ShakeWigglePrimitiveProps = ComponentProps<typeof motion.div>;

export function ShakeWigglePrimitive({ children, ...props }: ShakeWigglePrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {x: 0}}
      animate={{x: [0,-7,6,-4,3,0]}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.24, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
